    manifest modManifest
    finalizedBy 'reobfShadowJar'

    // CurseForge allows ONE file per project, so the two addons ride inside this jar: three @Mod, three
    // [[mods]] in the core's mods.toml. Their own mods.toml are left out (a jar can only have one) and stay
    // for their dev runs. Lazy closures + string task paths: the submodules depend on this project, so they
    // can't be read while this script is still evaluating.
    dependsOn ':dungeon:classes', ':species:classes'
    ['dungeon', 'species'].each { name ->
        from({ project(":${name}").sourceSets.main.output }) { exclude 'META-INF/mods.toml' }
    }
    duplicatesStrategy = DuplicatesStrategy.EXCLUDE // identical pack.mcmeta; the core's copy wins
}

